STORY = [('muranishi', '二億五千万用意したぞ。衛星の電波料だ、すぐに入金しろ。', "I brought the 250 million yen! It's for the satellite broadcast fee—wire it immediately.", [(355, '２億5000万 用意したぞ'), (357, '衛星の電波料だ すぐに入金しろ')], 'spelled numeral in kanji'), ('kacho', '状況が変われば条件も変わります。夢や希望にお金を出す時代は終わったんですよ。', 'When circumstances change, terms change too. The era of funding dreams and hopes is over.', [(358, '状況が変われば 条件も変わります'), (359, '夢や希望に お金を出す時代は 終わったんですよ')], ''), ('kacho', '初年度の契約見込みは十万件でしたよね？現在契約は何件ですか？', 'Your first-year forecast was one hundred thousand subscribers, right? How many do you have now?', [(363, '初年度の契約見込みは 10万件でしたよね'), (364, '現在 契約は何件ですか')], 'spelled numeral in kanji'), ('muranishi', 'もう千件だ。', 'Already a thousand.', [(365, 'もう1000件だ')], 'spelled numeral in kanji'), ('kacho', '七百六十三件。毎朝目覚めるだけで八百二十四万円ずつ減っています。無謀ですよね？', "Seven hundred sixty-three! Just waking up each morning loses you 8.24 million yen. Reckless, isn't it?", [(366, '763件'), (371, '毎朝 目覚めるだけで 824万円ずつ減っています'), (372, '無謀ですよね')], 'spelled numerals in kanji'), ('muranishi', 'じきに時代が追いついてくる。', 'The times will catch up with us before long.', [(373, 'じきに時代が追いついてくる')], ''), ('kacho', '暴走には誰も追いつけません。衛星への過剰投資で借金はまもなく四十億を超えますよ。', 'Nobody can catch up to a runaway train! Overinvestment in satellite will push your debt past four billion soon.', [(374, '暴走には 誰も追いつけません'), (376, '衛星への過剰投資で 借金は まもなく40億を超えますよ')], 'spelled numeral in kanji'), ('kacho', 'この会社は完全に病気だ。あなたは死亡間近の重病患者です。', 'This company is thoroughly sick—and you are a critically ill patient near death.', [(377, 'この会社は完全に病気だ'), (378, 'あなたは 死亡間近の重病患者です')], ''), ('muranishi', '御託はいい、すぐに入金しろ。', 'Spare me the lecture and wire the money now.', [(379, '御託はいい すぐに入金しろ')], ''), ('kacho', '愚かな死を選ぶ理由は何です？もう一度聞きます。', 'What is your reason for choosing a foolish death? I will ask you one final time.', [(381, '愚かな死を選ぶ理由は何です'), (382, 'もう一度 聞きます')], ''), ('kacho', '元本の返済に充てますか？それとも衛星の電波料に充てますか？', 'Will you apply this money toward loan principal, or toward the satellite broadcast fee?', [(383, '元本の返済に充てますか'), (384, 'それとも 衛星の電波料に 充てますか')], ''), ('muranishi', '衛星だ。', 'The satellite.', [(385, '衛星だ')], '')]
